export function findState(code: string): IndiaState | undefined {
  return INDIA_STATES.find((s) => String(s.code) === code);
}

export function findDistrict(state: IndiaState | undefined, code: string): IndiaDistrict | undefined {
  return state?.districts.find((d) => String(d.code) === code);
}
